﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { InjectCssNodeData } from '../../../types/schema';

export class InjectCssBlockHandler extends BaseBlockHandler<'inject_css'> {
  public readonly type = 'inject_css';

  async execute(node: { id: string; data: InjectCssNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const css = context.state.interpolate(node.data.css);
    await context.driver.injectCss(css, node.data.target, node.data.styleId);
    return this.success(node.id, 'default', { injected: true, target: node.data.target, styleId: node.data.styleId });
  }
}