﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { TabActionNodeData } from '../../../types/schema';

export class TabActionBlockHandler extends BaseBlockHandler<'tab_action'> {
  public readonly type = 'tab_action';

  async execute(node: { id: string; data: TabActionNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const { action, queryType, queryValue, saveUrlToVar, active } = node.data;
    let resultPayload: any = { action };

    switch (action) {
      case 'new_tab': {
        const targetUrl = node.data.url ? context.state.interpolate(node.data.url) : undefined;
        const res = await context.driver.createTab(targetUrl, active);
        if (saveUrlToVar && res.url) context.state.set(saveUrlToVar, res.url);
        resultPayload = { ...resultPayload, tabId: res.tabId, url: res.url };
        break;
      }
      case 'switch_tab': {
        const val = typeof queryValue === 'string' ? context.state.interpolate(queryValue) : queryValue;
        await context.driver.switchTab(queryType || 'title', val!);
        resultPayload = { ...resultPayload, queryType, queryValue: val };
        break;
      }
      case 'close_tab': {
        const val = typeof queryValue === 'string' ? context.state.interpolate(queryValue) : queryValue;
        await context.driver.closeTab(queryType, val!);
        resultPayload = { ...resultPayload, queryType, queryValue: val };
        break;
      }
      case 'get_current_url': {
        const currentUrl = await context.driver.getCurrentUrl();
        if (saveUrlToVar) context.state.set(saveUrlToVar, currentUrl);
        resultPayload = { ...resultPayload, currentUrl };
        break;
      }
    }

    return this.success(node.id, 'default', resultPayload);
  }
}