﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { ScrollNodeData } from '../../../types/schema';

export class ScrollBlockHandler extends BaseBlockHandler<'scroll'> {
  public readonly type = 'scroll';

  async execute(node: { id: string; data: ScrollNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const selector = node.data.selector ? context.state.interpolate(node.data.selector) : undefined;
    await context.driver.scroll(
      node.data.target,
      selector,
      node.data.selectorType,
      node.data.deltaX,
      node.data.deltaY,
      node.data.smooth
    );
    return this.success(node.id, 'default', {
      target: node.data.target,
      selector,
      deltaX: node.data.deltaX,
      deltaY: node.data.deltaY,
    });
  }
}