﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { StartNodeData } from '../../../types/schema';

export class StartBlockHandler extends BaseBlockHandler<'start'> {
  public readonly type = 'start';

  async execute(node: { id: string; data: StartNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const trigger = node.data.triggerType || 'manual';
    context.log('info', `Gatilho acionado: ${trigger}`, node.id);
    return this.success(node.id, 'default', { trigger, timestamp: Date.now() });
  }
}