﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { HoverFocusNodeData } from '../../../types/schema';

export class HoverFocusBlockHandler extends BaseBlockHandler<'hover_focus'> {
  public readonly type = 'hover_focus';

  async execute(node: { id: string; data: HoverFocusNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const selector = context.state.interpolate(node.data.selector);
    await context.driver.hoverOrFocus(selector, node.data.selectorType, node.data.action, node.data.timeoutMs);
    return this.success(node.id, 'default', {
      selector,
      action: node.data.action,
    });
  }
}