﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { WaitForElementNodeData } from '../../../types/schema';

export class WaitForElementBlockHandler extends BaseBlockHandler<'wait_for_element'> {
  public readonly type = 'wait_for_element';

  async execute(node: { id: string; data: WaitForElementNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const selector = context.state.interpolate(node.data.selector);
    const found = await context.driver.waitForElement(selector, node.data.selectorType, node.data.state, node.data.timeoutMs);
    return this.success(node.id, 'default', {
      found,
      selector,
      state: node.data.state,
    });
  }
}