﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { InjectHtmlNodeData } from '../../../types/schema';

export class InjectHtmlBlockHandler extends BaseBlockHandler<'inject_html'> {
  public readonly type = 'inject_html';

  async execute(node: { id: string; data: InjectHtmlNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const html = context.state.interpolate(node.data.html);
    const selector = context.state.interpolate(node.data.targetSelector);
    await context.driver.injectHtml(html, selector, node.data.position, node.data.selectorType);
    return this.success(node.id, 'default', { injected: true, targetSelector: selector, position: node.data.position });
  }
}