﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { ScrapeListNodeData } from '../../../types/schema';

export class ScrapeListBlockHandler extends BaseBlockHandler<'scrape_list'> {
  public readonly type = 'scrape_list';

  async execute(node: { id: string; data: ScrapeListNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const selector = context.state.interpolate(node.data.selector);
    const items = await context.driver.scrapeList(
      selector,
      node.data.selectorType,
      node.data.fields,
      node.data.maxItems,
      node.data.timeoutMs
    );

    if (node.data.saveToVar) {
      context.state.set(node.data.saveToVar, items);
    }
    context.log('info', `Lista raspada (${items.length} itens) salva em [${node.data.saveToVar || 'output'}]`, node.id);

    return this.success(node.id, 'default', {
      [node.data.saveToVar || 'items']: items,
      items,
      count: items.length,
    });
  }
}