﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { NavigateNodeData } from '../../../types/schema';

export class NavigateBlockHandler extends BaseBlockHandler<'navigate'> {
  public readonly type = 'navigate';

  async execute(node: { id: string; data: NavigateNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const url = context.state.interpolate(node.data.url);
    context.log('info', `Navegando para URL: ${url}`, node.id);
    await context.driver.navigateTo(url, node.data.waitUntil, node.data.timeoutMs);
    return this.success(node.id, 'default', { url, waitUntil: node.data.waitUntil });
  }
}