﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { ExportFileNodeData } from '../../../types/schema';

export class ExportFileBlockHandler extends BaseBlockHandler<'export_file'> {
  public readonly type = 'export_file';

  async execute(node: { id: string; data: ExportFileNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const rawData = context.state.get(node.data.sourceVar);
    const filename = context.state.interpolate(node.data.filename);
    let content = '';
    let mimeType = 'text/plain';

    if (node.data.format === 'json') {
      content = JSON.stringify(rawData, null, 2);
      mimeType = 'application/json';
    } else if (node.data.format === 'csv') {
      mimeType = 'text/csv';
      const delimiter = node.data.csvDelimiter || ',';
      if (Array.isArray(rawData) && rawData.length > 0) {
        const headers = Object.keys(rawData[0]);
        const headerRow = headers.join(delimiter);
        const rows = rawData.map((item) =>
          headers.map((h) => JSON.stringify(item[h] ?? '')).join(delimiter)
        );
        content = [headerRow, ...rows].join('\n');
      }
    }

    await context.driver.downloadFile(content, filename, mimeType);
    context.log('info', `Arquivo ${filename} exportado com sucesso.`, node.id);
    return this.success(node.id, 'default', { filename, format: node.data.format, size: content.length });
  }
}