﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { TypeInputNodeData } from '../../../types/schema';

export class TypeInputBlockHandler extends BaseBlockHandler<'type_input'> {
  public readonly type = 'type_input';

  async execute(node: { id: string; data: TypeInputNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const selector = context.state.interpolate(node.data.selector);
    const text = context.state.interpolate(node.data.text);

    await context.driver.typeText(
      selector,
      node.data.selectorType,
      text,
      node.data.mode,
      node.data.minTypingDelayMs,
      node.data.maxTypingDelayMs,
      node.data.clearBeforeTyping,
      node.data.pressEnterAfter,
      node.data.timeoutMs
    );
    return this.success(node.id, 'default', {
      typed: true,
      selector,
      textLength: text.length,
      mode: node.data.mode,
    });
  }
}