﻿/**
 * Ponto Central de Handlers Padrão de Execução
 * Re-exporta as classes individuais de blocos em seus arquivos modulares
 * e expõe o registro orientado a objetos no motor.
 */

import { ExecutionEngine } from './ExecutionEngine';
import { defaultBlockRegistry } from './blocks/BlockRegistry';

// Re-exports da infraestrutura de blocos
export * from './blocks/BaseBlockHandler';
export * from './blocks/BlockRegistry';

// Flow
export { StartBlockHandler as StartNodeHandler, StartBlockHandler } from './blocks/flow/StartBlock';
export { DelayBlockHandler as DelayNodeHandler, DelayBlockHandler } from './blocks/flow/DelayBlock';
export { SwitchBlockHandler as SwitchNodeHandler, SwitchBlockHandler } from './blocks/flow/SwitchBlock';
export { IfElementExistsBlockHandler as IfElementExistsNodeHandler, IfElementExistsBlockHandler } from './blocks/flow/IfElementExistsBlock';

// Navigation
export { NavigateBlockHandler as NavigateNodeHandler, NavigateBlockHandler } from './blocks/navigation/NavigateBlock';
export { TabActionBlockHandler as TabActionNodeHandler, TabActionBlockHandler } from './blocks/navigation/TabActionBlock';
export { HistoryNavigationBlockHandler as HistoryNavigationNodeHandler, HistoryNavigationBlockHandler } from './blocks/navigation/HistoryNavigationBlock';

// DOM
export { ClickElementBlockHandler as ClickElementNodeHandler, ClickElementBlockHandler } from './blocks/dom/ClickElementBlock';
export { TypeInputBlockHandler as TypeInputNodeHandler, TypeInputBlockHandler } from './blocks/dom/TypeInputBlock';
export { PressKeyBlockHandler as PressKeyNodeHandler, PressKeyBlockHandler } from './blocks/dom/PressKeyBlock';
export { HoverFocusBlockHandler as HoverFocusNodeHandler, HoverFocusBlockHandler } from './blocks/dom/HoverFocusBlock';
export { ScrollBlockHandler as ScrollNodeHandler, ScrollBlockHandler } from './blocks/dom/ScrollBlock';
export { WaitForElementBlockHandler as WaitForElementNodeHandler, WaitForElementBlockHandler } from './blocks/dom/WaitForElementBlock';

// Data
export { SetVariableBlockHandler as SetVariableNodeHandler, SetVariableBlockHandler } from './blocks/data/SetVariableBlock';
export { HttpRequestBlockHandler as HttpRequestNodeHandler, HttpRequestBlockHandler } from './blocks/data/HttpRequestBlock';
export { ExtractDataBlockHandler as ExtractDataNodeHandler, ExtractDataBlockHandler } from './blocks/data/ExtractDataBlock';
export { ScrapeListBlockHandler as ScrapeListNodeHandler, ScrapeListBlockHandler } from './blocks/data/ScrapeListBlock';
export { ExportFileBlockHandler as ExportFileNodeHandler, ExportFileBlockHandler } from './blocks/data/ExportFileBlock';

// Injection
export { InjectJavascriptBlockHandler as InjectJavascriptNodeHandler, InjectJavascriptBlockHandler } from './blocks/injection/InjectJavascriptBlock';
export { InjectHtmlBlockHandler as InjectHtmlNodeHandler, InjectHtmlBlockHandler } from './blocks/injection/InjectHtmlBlock';
export { InjectCssBlockHandler as InjectCssNodeHandler, InjectCssBlockHandler } from './blocks/injection/InjectCssBlock';
export { WebComponentBlockHandler as WebComponentNodeHandler, WebComponentBlockHandler } from './blocks/injection/WebComponentBlock';

/**
 * Função de vinculação dos handlers ao motor de execução via BlockRegistry
 */
export function registerAllDefaultHandlers(engine: ExecutionEngine): void {
  defaultBlockRegistry.bindToEngine(engine);
}