﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { ExtractDataNodeData } from '../../../types/schema';

export class ExtractDataBlockHandler extends BaseBlockHandler<'extract_data'> {
  public readonly type = 'extract_data';

  async execute(node: { id: string; data: ExtractDataNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const selector = context.state.interpolate(node.data.selector);
    const data = await context.driver.extractData(
      selector,
      node.data.selectorType,
      node.data.extractType,
      node.data.attributeName,
      node.data.timeoutMs
    );

    if (node.data.saveToVar) {
      context.state.set(node.data.saveToVar, data);
    }
    context.log('info', `Dado extraído salvo em [${node.data.saveToVar || 'output'}]`, node.id);

    const resultPayload = node.data.saveToVar ? { [node.data.saveToVar]: data, value: data } : { value: data };
    return this.success(node.id, 'default', resultPayload);
  }
}