﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { ClickElementNodeData } from '../../../types/schema';

export class ClickElementBlockHandler extends BaseBlockHandler<'click_element'> {
  public readonly type = 'click_element';

  async execute(node: { id: string; data: ClickElementNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const selector = context.state.interpolate(node.data.selector);
    await context.driver.clickElement(
      selector,
      node.data.selectorType,
      node.data.clickType,
      node.data.timeoutMs,
      node.data.clickCoordinates
    );
    return this.success(node.id, 'default', {
      clicked: true,
      selector,
      clickType: node.data.clickType,
    });
  }
}