﻿/**
 * Gerenciador Orientado a Objetos de Registro de Blocos (BlockRegistry)
 * Mantém o catálogo de executores instanciados e vincula-os ao ExecutionEngine
 */

import { NodeType } from '../../types/schema';
import { ExecutionEngine } from '../ExecutionEngine';
import { BaseBlockHandler } from './BaseBlockHandler';

// Flow
import { StartBlockHandler } from './flow/StartBlock';
import { DelayBlockHandler } from './flow/DelayBlock';
import { SwitchBlockHandler } from './flow/SwitchBlock';
import { IfElementExistsBlockHandler } from './flow/IfElementExistsBlock';

// Navigation
import { NavigateBlockHandler } from './navigation/NavigateBlock';
import { TabActionBlockHandler } from './navigation/TabActionBlock';
import { HistoryNavigationBlockHandler } from './navigation/HistoryNavigationBlock';

// DOM
import { ClickElementBlockHandler } from './dom/ClickElementBlock';
import { TypeInputBlockHandler } from './dom/TypeInputBlock';
import { PressKeyBlockHandler } from './dom/PressKeyBlock';
import { HoverFocusBlockHandler } from './dom/HoverFocusBlock';
import { ScrollBlockHandler } from './dom/ScrollBlock';
import { WaitForElementBlockHandler } from './dom/WaitForElementBlock';

// Data
import { SetVariableBlockHandler } from './data/SetVariableBlock';
import { HttpRequestBlockHandler } from './data/HttpRequestBlock';
import { ExtractDataBlockHandler } from './data/ExtractDataBlock';
import { ScrapeListBlockHandler } from './data/ScrapeListBlock';
import { ExportFileBlockHandler } from './data/ExportFileBlock';

// Injection
import { InjectJavascriptBlockHandler } from './injection/InjectJavascriptBlock';
import { InjectHtmlBlockHandler } from './injection/InjectHtmlBlock';
import { InjectCssBlockHandler } from './injection/InjectCssBlock';
import { WebComponentBlockHandler } from './injection/WebComponentBlock';

export class BlockRegistry {
  private blocks: Map<NodeType, BaseBlockHandler<any>> = new Map();

  constructor() {
    this.registerDefaults();
  }

  /**
   * Registra uma instância de bloco
   */
  public register<T extends NodeType>(block: BaseBlockHandler<T>): this {
    this.blocks.set(block.type, block);
    return this;
  }

  /**
   * Obtém a instância do executor de um bloco pelo tipo
   */
  public get<T extends NodeType>(type: T): BaseBlockHandler<T> | undefined {
    return this.blocks.get(type) as BaseBlockHandler<T> | undefined;
  }

  /**
   * Verifica se um bloco está registrado
   */
  public has(type: NodeType): boolean {
    return this.blocks.has(type);
  }

  /**
   * Remove um bloco do registro
   */
  public unregister(type: NodeType): boolean {
    return this.blocks.delete(type);
  }

  /**
   * Retorna todos os blocos registrados
   */
  public getAll(): BaseBlockHandler[] {
    return Array.from(this.blocks.values());
  }

  /**
   * Vincula e registra todos os blocos em uma instância de ExecutionEngine
   */
  public bindToEngine(engine: ExecutionEngine): void {
    for (const [type, handler] of this.blocks.entries()) {
      engine.registerHandler(type, handler);
    }
  }

  /**
   * Registra todas as implementações padrão dos blocos
   */
  private registerDefaults(): void {
    // Flow
    this.register(new StartBlockHandler());
    this.register(new DelayBlockHandler());
    this.register(new SwitchBlockHandler());
    this.register(new IfElementExistsBlockHandler());

    // Navigation
    this.register(new NavigateBlockHandler());
    this.register(new TabActionBlockHandler());
    this.register(new HistoryNavigationBlockHandler());

    // DOM
    this.register(new ClickElementBlockHandler());
    this.register(new TypeInputBlockHandler());
    this.register(new PressKeyBlockHandler());
    this.register(new HoverFocusBlockHandler());
    this.register(new ScrollBlockHandler());
    this.register(new WaitForElementBlockHandler());

    // Data
    this.register(new SetVariableBlockHandler());
    this.register(new HttpRequestBlockHandler());
    this.register(new ExtractDataBlockHandler());
    this.register(new ScrapeListBlockHandler());
    this.register(new ExportFileBlockHandler());

    // Injection
    this.register(new InjectJavascriptBlockHandler());
    this.register(new InjectHtmlBlockHandler());
    this.register(new InjectCssBlockHandler());
    this.register(new WebComponentBlockHandler());
  }
}

// Instância singleton padrão do registro de blocos
export const defaultBlockRegistry = new BlockRegistry();