﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { PressKeyNodeData } from '../../../types/schema';

export class PressKeyBlockHandler extends BaseBlockHandler<'press_key'> {
  public readonly type = 'press_key';

  async execute(node: { id: string; data: PressKeyNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const selector = node.data.selector ? context.state.interpolate(node.data.selector) : undefined;
    await context.driver.pressKey(node.data.key, node.data.modifiers, selector, node.data.selectorType);
    return this.success(node.id, 'default', {
      key: node.data.key,
      modifiers: node.data.modifiers || [],
      selector,
    });
  }
}