﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { InjectJavascriptNodeData } from '../../../types/schema';

export class InjectJavascriptBlockHandler extends BaseBlockHandler<'inject_javascript'> {
  public readonly type = 'inject_javascript';

  async execute(node: { id: string; data: InjectJavascriptNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const code = context.state.interpolate(node.data.code);
    const args = (node.data.args || []).map((arg: string) => context.state.get(arg));
    const result = await context.driver.injectScript(code, node.data.context, args);

    if (node.data.saveResultToVar) {
      context.state.set(node.data.saveResultToVar, result);
    }

    // A saída fica transferível para os próximos blocos via $json
    const outputData = typeof result === 'object' && result !== null ? result : { result };
    return this.success(node.id, 'default', outputData);
  }
}