﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { SwitchNodeData } from '../../../types/schema';

export class SwitchBlockHandler extends BaseBlockHandler<'switch'> {
  public readonly type = 'switch';

  async execute(node: { id: string; data: SwitchNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const { cases, hasDefaultBranch } = node.data;

    for (const testCase of cases) {
      let passed = false;

      if (Array.isArray(testCase.conditionGroups) && testCase.conditionGroups.length > 0) {
        passed = context.state.evaluateConditionGroups(testCase.conditionGroups);
      } else if (Array.isArray(testCase.rules) && testCase.rules.length > 0) {
        passed = context.state.evaluateRulesGroup(testCase.rules, testCase.logicalOperator || 'and');
      } else if (testCase.evaluationMode === 'js_eval' || (testCase.jsExpression && !testCase.operator)) {
        const result = context.state.evaluateJsExpression(testCase.jsExpression || '');
        passed = Boolean(result);
      } else {
        passed = context.state.evaluateCondition(
          testCase.leftOperand,
          testCase.operator,
          testCase.rightOperand
        );
      }

      if (passed) {
        context.log('info', `Condição satisfeita para o caso [${testCase.label || testCase.id}]`, node.id);
        return this.success(node.id, testCase.id, { matchedCase: testCase.id, label: testCase.label });
      }
    }

    if (hasDefaultBranch) {
      context.log('info', 'Nenhuma condição satisfeita. Seguindo caminho default.', node.id);
      return this.success(node.id, 'default', { matchedCase: 'default' });
    }

    return this.success(node.id, undefined, { matchedCase: null });
  }
}