﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { HistoryNavigationNodeData } from '../../../types/schema';

export class HistoryNavigationBlockHandler extends BaseBlockHandler<'history_navigation'> {
  public readonly type = 'history_navigation';

  async execute(node: { id: string; data: HistoryNavigationNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    await context.driver.navigateHistory(node.data.action, node.data.ignoreCache);
    return this.success(node.id, 'default', { action: node.data.action, ignoreCache: node.data.ignoreCache });
  }
}