﻿import { BaseBlockHandler } from '../BaseBlockHandler';
import { ExecutionContext, NodeExecutionResult } from '../../ExecutionContext';
import { WebComponentNodeData } from '../../../types/schema';

export class WebComponentBlockHandler extends BaseBlockHandler<'web_component'> {
  public readonly type = 'web_component';

  async execute(node: { id: string; data: WebComponentNodeData }, context: ExecutionContext): Promise<NodeExecutionResult> {
    const html = context.state.interpolate(node.data.html);
    const css = context.state.interpolate(node.data.css);
    const js = context.state.interpolate(node.data.js);
    await context.driver.injectWebComponent(html, css, js, node.data.containerId, node.data.mode);
    return this.success(node.id, 'default', {
      injected: true,
      containerId: node.data.containerId,
      mode: node.data.mode,
    });
  }
}