﻿/**
 * Classe Base Abstrata Orientada a Objetos para todos os Blocos de Automação
 */
import { NodeType, AnyAutomationNode } from '../../types/schema';
import { ExecutionContext, INodeHandler, NodeExecutionResult } from '../ExecutionContext';

export abstract class BaseBlockHandler<T extends NodeType = NodeType> implements INodeHandler<T> {
  public abstract readonly type: T;

  public abstract execute(
    node: AnyAutomationNode & { type: T },
    context: ExecutionContext
  ): Promise<NodeExecutionResult>;

  /**
   * Constrói resultado padronizado de sucesso
   */
  protected success(nodeId: string, outputHandle: string = 'default', outputData?: any): NodeExecutionResult {
    return {
      nodeId,
      status: 'success',
      outputHandle,
      outputData,
      startTime: 0,
      endTime: 0,
      durationMs: 0,
    };
  }

  /**
   * Constrói resultado padronizado de falha
   */
  protected error(nodeId: string, err: any): NodeExecutionResult {
    const errorObj = err instanceof Error ? err : new Error(String(err));
    return {
      nodeId,
      status: 'failed',
      error: errorObj,
      startTime: 0,
      endTime: 0,
      durationMs: 0,
    };
  }
}